const base=new URL('../',document.currentScript.src).pathname;const link=p=>base+p;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let paused=reduced;const route=location.pathname.slice(base.length).split('/')[0];const page=['work','about','contact'].includes(route)?route:'home';
const projects=[{id:'openedmind',name:'OpenedMind',category:'Digital',text:'An exploration of emotion recognition, conversational support, and the human side of technology.',url:'https://openedmind.org'},{id:'visual',name:'Visual studies',category:'Visual',text:'A growing archive of photography, typography, and visual experiments. New studies are on the way.'},{id:'writing',name:'Words in transit',category:'Writing',text:'Poems, short pieces, and reflections. New writing is on the way.'}];
// Add your destination URLs here. Blank destinations show a notice instead of opening a guessed account.
const socials={youtube:'',instagram:'https://www.instagram.com/amauryca_/',discord:'',twitch:''};
function flapChar(char){const c=char===' '?'&nbsp;':char;return `<span class="flap ${char===' '?'space':''}" data-char="${char}" aria-hidden="true"><span class="half top"><span>${c}</span></span><span class="half bottom"><span>${c}</span></span></span>`}
function display(text,id='',classes=''){return `<span ${id?`id="${id}"`:''} class="flap-display ${classes}" aria-label="${text}">${[...text].map(flapChar).join('')}</span>`}
function header(){return `<header><a class="brand" href="${base}" aria-label="Athetis home">Athetis</a>${display(new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false}),'clock','clock-flaps')}</header>`}
function footer(){return `<footer><span class="status-display">${display('now boarding','status')}</span><button class="motion" id="motion">${paused?'resume motion':'pause motion'}</button></footer><div id="notice" class="notice" role="status" hidden></div>`}
function home(){const items=[{label:'website',href:link('work/')},...Object.entries(socials).map(([label,href])=>({label,href,social:true})),{label:'contact',href:link('contact/')}];return `<main class="home"><nav class="menu" aria-label="Athetis destinations">${items.map(s=>s.href?`<a class="menu-item" href="${s.href}" ${s.social?'target="_blank" rel="noopener noreferrer"':''}>${display(s.label)}</a>`:`<button class="menu-item" data-missing="${s.label}">${display(s.label)}</button>`).join('')}</nav></main>`}
function nav(){return `<nav class="subnav" aria-label="Pages"><a href="${base}">home</a><a href="${link('work/')}">work</a><a href="${link('about/')}">about</a><a href="${link('contact/')}">contact</a></nav>`}
function rows(filter='All'){return projects.filter(p=>filter==='All'||p.category===filter).map(p=>`<section><button class="project-row" data-project="${p.id}" aria-expanded="false" aria-controls="detail-${p.id}"><h3>${p.name}</h3><small>${p.category} / view +</small></button><div class="project-detail" id="detail-${p.id}" hidden><p>${p.text}</p>${p.url?`<a class="text-link" href="${p.url}" target="_blank" rel="noopener noreferrer">Visit project</a>`:''}</div></section>`).join('')}
function work(){return `<main class="inner">${nav()}<h1>${display('selected work')}</h1><div class="filters" role="group" aria-label="Project filters">${['All','Digital','Visual','Writing'].map(f=>`<button class="filter ${f==='All'?'active':''}" data-filter="${f}" aria-pressed="${f==='All'}">${f}</button>`).join('')}</div><div id="projects">${rows()}</div></main>`}
function about(){return `<main class="inner">${nav()}<h1>${display('about athetis')}</h1><p>A platform for digital projects, visual experiments, and words.</p><p>Built on curiosity. Always in motion.</p><a class="text-link" href="${link('work/')}">Explore the work</a></main>`}
function contact(){return `<main class="inner">${nav()}<h1>${display('contact')}</h1><p>Start a conversation.</p><div class="links"><a href="${socials.instagram}" target="_blank" rel="noopener noreferrer">${display('instagram')}</a><a href="${link('about/')}">${display('about athetis')}</a></div></main>`}
document.title=page==='home'?'Athetis':`${page[0].toUpperCase()+page.slice(1)} — Athetis`;document.getElementById('app').innerHTML=header()+({home,work,about,contact}[page]())+footer();
let generation=0;const timers=new Set();function later(fn,delay){const id=setTimeout(()=>{timers.delete(id);fn()},delay);timers.add(id)}
function setFlap(cell,next,animate=true){if(!cell||cell.dataset.char===next)return;const old=cell.dataset.char;cell.dataset.char=next;cell.classList.toggle('space',next===' ');const n=next===' '?'&nbsp;':next;const o=old===' '?'&nbsp;':old;cell.innerHTML=`<span class="half top"><span>${n}</span></span><span class="half bottom"><span>${n}</span></span>`;if(animate&&!paused){cell.insertAdjacentHTML('beforeend',`<span class="half top flip-top"><span>${o}</span></span><span class="half bottom flip-bottom"><span>${n}</span></span>`);later(()=>cell.querySelectorAll('.flip-top,.flip-bottom').forEach(x=>x.remove()),370)}}
function update(el,text,{scramble=false}={}){if(!el)return;const chars=[...text],old=[...el.querySelectorAll('.flap')];el.setAttribute('aria-label',text);if(paused){el.innerHTML=chars.map(flapChar).join('');return}while(el.children.length<chars.length)el.insertAdjacentHTML('beforeend',flapChar(' '));while(el.children.length>chars.length)el.lastElementChild.remove();const cells=[...el.children],alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ';chars.forEach((c,i)=>{if(!scramble&&cells[i].dataset.char===c)return;const delay=i*28;if(scramble){for(let k=0;k<3;k++)later(()=>setFlap(cells[i],alphabet[(i*5+k*7)%26]),delay+k*390);later(()=>setFlap(cells[i],c),delay+1170)}else later(()=>setFlap(cells[i],c),delay)})}
function sweep(el){const text=el.getAttribute('aria-label');if(!paused&&el.dataset.busy!=='true'){el.dataset.busy='true';update(el,text,{scramble:true});later(()=>el.dataset.busy='false',1700)}}
document.querySelectorAll('.menu-item').forEach(el=>{el.addEventListener('mouseenter',()=>sweep(el.querySelector('.flap-display')));el.addEventListener('focus',()=>sweep(el.querySelector('.flap-display')))});
document.querySelectorAll('[data-missing]').forEach(b=>b.addEventListener('click',()=>{const n=document.getElementById('notice');n.textContent=b.dataset.missing+' link coming soon.';n.hidden=false;later(()=>n.hidden=true,3500)}));
function bindProjects(){document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!open));document.getElementById('detail-'+b.dataset.project).hidden=open;b.querySelector('small').textContent=projects.find(p=>p.id===b.dataset.project).category+(open?' / view +':' / close −')}))}bindProjects();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.getElementById('projects').innerHTML=rows(b.dataset.filter);bindProjects()}));
const messages=['now boarding','next stop athetis','mind the gap'];let messageIndex=0;setInterval(()=>{if(!paused)update(document.getElementById('status'),messages[++messageIndex%messages.length],{scramble:true})},6500);setInterval(()=>update(document.getElementById('clock'),new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false})),1000);
document.getElementById('motion').addEventListener('click',e=>{paused=!paused;if(paused){timers.forEach(clearTimeout);timers.clear();document.querySelectorAll('.flap-display').forEach(el=>{el.innerHTML=[...el.getAttribute('aria-label')].map(flapChar).join('');delete el.dataset.busy})}e.target.textContent=paused?'resume motion':'pause motion'});
if(!paused)document.querySelectorAll('.menu .flap-display').forEach((el,i)=>later(()=>sweep(el),i*90));
